import{_ as o,l as n,o as e,c as r,v as t,p as c,x as d,d as l,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"欧几里得与扩展欧几里得","description":"","frontmatter":{"title":"欧几里得与扩展欧几里得","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/euclid-extended.md","filePath":"cs/euclid-extended.md","lastUpdated":1789023840000}'),h={name:"cs/euclid-extended.md"};function m(u,a,b,g,_,x){const i=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="欧几里得与扩展欧几里得" tabindex="-1">欧几里得与扩展欧几里得 <a class="header-anchor" href="#欧几里得与扩展欧几里得" aria-label="Permalink to &quot;欧几里得与扩展欧几里得&quot;">​</a></h1><div class="epigraph"><p>$\\gcd(a,b)=\\gcd(b,a\\bmod b)$；回溯系数得 $ax+by=\\gcd$。$\\gcd(a,n)=1$ 时 $x$ 就是模 $n$ 的逆。</p><footer>—— 据 Euclid, Elements 卷 VII；Knuth, TAOCP 卷 2 整理</footer></div><p>上一课<a href="/cs/modular-arithmetic">模运算</a> 留下 \\(ax\\equiv 1\\pmod n\\)。缺口是<strong>欧几里得算法</strong>与扩展形式。不重写剩余类。复杂度：除法步数 \\(O(\\log\\min(a,b))\\)（最坏 Fibonacci）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\gcd\\) 与最小正线性组合重合：存在 \\(x,y\\)，\\(ax+by=\\gcd(a,b)\\)（Bézout）。扩展欧几里得在递归同时带回 \\(x,y\\)。\\(\\gcd(a,n)=1\\iff a\\) 在 \\(\\mathbb{Z}/n\\mathbb{Z}\\) 可逆，\\(a^{-1}\\equiv x\\pmod n\\)。\\(\\gcd\\gt 1\\) 则 \\(ax\\equiv 1\\) 无解；\\(ax\\equiv b\\) 有解当 \\(\\gcd\\mid b\\)。</p><p>二进制 gcd、Lehmer 加速是实现，本课标准除法版。</p><h3 id="不是「约分分数」的小学课" tabindex="-1">不是「约分分数」的小学课 <a class="header-anchor" href="#不是「约分分数」的小学课" aria-label="Permalink to &quot;不是「约分分数」的小学课&quot;">​</a></h3><p>对象是任意大整数，密码里几百比特。算法要停在 \\(\\log\\) 步，不能试除到 \\(\\sqrt a\\) 来求 gcd。</p><p><span class="marginnote">欧几里得原本对线段。Knuth 分析步数与 Fibonacci 最坏。本课不证 Lamé。RSA 解密指数 \\(d\\) 用扩展欧几里得求 \\(e\\) 对 \\(\\varphi(n)\\) 的逆，后课欧拉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>手算 \\(\\gcd(240,46)\\) 并列 \\(x,y\\)。写出 \\(a^{-1}\\bmod n\\) 当且仅当互素。点名：求逆失败即发现与 \\(n\\) 不互素——RSA 模上这几乎是分解，实践中信息位随机不会碰到。</p>',11)),(e(),c(p,null,{default:d(()=>[s(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22a%2C%20b%22%5D%20--%3E%20EUC%5B%22%E8%BE%97%E8%BD%AC%E7%9B%B8%E9%99%A4%22%5D%0A%20%20EUC%20--%3E%20G%5B%22gcd%22%5D%0A%20%20EUC%20--%3E%20BEZ%5B%22B%C3%A9zout%20x%2C%20y%22%5D%0A%20%20BEZ%20--%3E%20INV%5B%22gcd%3D1%20%E2%87%92%20%E6%A8%A1%E9%80%86%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了逆，乘法群 \\((\\mathbb{Z}/n\\mathbb{Z})^\\times\\) 才真的是群（下一课欧拉函数数它的阶）。高斯消元在模 \\(p\\) 上需要每步求逆。扩展欧几里得也是格基、RSA CRT 实现的组件。</p><p>不要用费马小定理 \\(a^{p-2}\\) 当本课主算法——那要 \\(p\\) 素数且更贵。</p><p>Lamé：最坏步数由连续 Fibonacci 达到。二进制 gcd 用移位，硬件友好。模逆失败返回 \\(\\gcd\\neq 1\\)：RSA 随机消息碰到 \\(p\\) 的概率可忽略。线性方程 \\(ax\\equiv b\\pmod n\\) 有 \\(\\gcd\\) 个解当 \\(\\gcd\\mid b\\)，解之间差 \\(n/\\gcd\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入连分数攻击，不证素性。后课默认：互素则可逆，逆由扩展欧几里得。下一课费马与欧拉，给指数运算减指数。</p><p>Bézout 系数就是模逆（当 gcd 为 1）。算法对数步，适合密码整数。费马 \\(a^{p-2}\\) 也能求逆，但更贵且要素数；本课主算法是扩展欧几里得。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧几里得算 gcd；扩展给出 Bézout 系数。</li><li>\\(\\gcd(a,n)=1\\iff\\) 模逆存在。</li><li>步数对数，适合大整数。</li><li>出处：Euclid；Knuth, TAOCP 卷 2。</li></ul>',9))])}const A=o(h,[["render",m]]);export{E as __pageData,A as default};
